import { test, expect } from '@playwright/test';

test.describe('CRUD Operations - Assign Category', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should display category dropdown', async ({ page }) => {
    const dropdown = page.getByRole('combobox', { name: /category/i });
    await expect(dropdown).toBeVisible();
  });

  test('should assign a category to a record', async ({ page }) => {
    const dropdown = page.getByRole('combobox', { name: /category/i });
    await dropdown.selectOption('category-1');

    const assignButton = page.getByRole('button', { name: /assign/i });
    await assignButton.click();

    const successMessage = page.getByText(/category assigned successfully/i);
    await expect(successMessage).toBeVisible();
  });
});
